g=[[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]]
# fill intermediate cells between consecutive markers in rows and columns
out=[r[:] for r in g]
for r,row in enumerate(g):
    cs=[c for c,x in enumerate(row) if x==5]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): out[r][c]=3
for c in range(len(g[0])):
    rs=[r for r in range(len(g)) if g[r][c]==5]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): out[r][c]=3
out

pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==5]
for i,(r,c) in enumerate(pts):
 for s,d in pts[i+1:]:
  if abs(s-r)==abs(d-c) and s!=r:
   dr=1 if s>r else -1; dc=1 if d>c else -1
   rr,cc=r+dr,c+dc
   while (rr,cc)!=(s,d):
    if out[rr][cc]!=5: out[rr][cc]=3
    rr+=dr;cc+=dc
out
